function renderAdmin(s,c){if(s==='inicio'){setHeader('Inicio');const u=getCollection('usuarios'),r=getCollection('reportes');c.innerHTML=statCards([['Usuarios',u.length],['Alumnos',u.filter(x=>x.rol==='ALUMNO').length],['Materias',getCollection('materias').length],['Reportes abiertos',r.filter(x=>x.estado!=='RESUELTO').length]])+`<div class="section-head"><h2>Resumen</h2></div><div class="grid"><div class="card"><strong>Roles registrados</strong><p class="muted">ADMIN, ALUMNO, PADRE y MANTENIMIENTO.</p></div><div class="card"><strong>Avisos activos</strong><p class="muted">${getCollection('avisos').length} avisos disponibles.</p></div><div class="card"><strong>Eventos</strong><p class="muted">${getCollection('eventos').length} eventos en calendario.</p></div></div>`}else if(s==='usuarios'){setHeader('Usuarios');const a=getCollection('usuarios');c.innerHTML=`<div class="section-head"><h2>Usuarios</h2><button class="btn primary" onclick="newUser()">+ Crear usuario</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${a.map(u=>`<tr><td>${escapeHTML(u.nombre)}</td><td>${escapeHTML(u.email)}</td><td>${u.rol}</td><td><span class="badge">${u.activo?'ACTIVO':'INACTIVO'}</span></td><td><button class="btn secondary" onclick="toggleUser('${u.id}')">${u.activo?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div>`}else if(s==='materias'){setHeader('Materias');c.innerHTML=`<div class="section-head"><h2>Materias</h2><button class="btn primary" onclick="newSubject()">+ Agregar materia</button></div><div class="grid">${getCollection('materias').map(m=>`<div class="card subject"><strong>${escapeHTML(m.nombre)}</strong><small>${escapeHTML(m.docente)}</small><small>Grupo: ${escapeHTML(m.grupo)}</small></div>`).join('')}</div>`}else if(s==='avisos'){setHeader('Avisos');c.innerHTML=`<div class="section-head"><h2>Avisos</h2><button class="btn primary" onclick="newNotice()">+ Nuevo aviso</button></div><div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}else if(s==='reportes'){setHeader('Reportes');c.innerHTML=`<div class="section-head"><h2>Reportes de mantenimiento</h2></div><div class="card">${getCollection('reportes').map(reportRow).join('')}</div>`}}
function newUser(){modal('Crear usuario',`<form><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>Correo<input name="email" type="email" required></label><label>Contraseña<input name="password" value="123456" required></label><label>Rol<select name="rol"><option>ADMIN</option><option>ALUMNO</option><option>PADRE</option><option>MANTENIMIENTO</option></select></label></div><div class="actions"><button class="btn primary">Crear</button></div></form>`,f=>{const a=getCollection('usuarios');a.push({id:uid('u'),nombre:f.get('nombre'),email:f.get('email'),password:f.get('password'),rol:f.get('rol'),activo:true});saveCollection('usuarios',a);document.getElementById('modalRoot').innerHTML='';render('usuarios');showToast('Usuario creado')})}
function toggleUser(id){const a=getCollection('usuarios'),u=a.find(x=>x.id===id);if(u&&u.id!==user.id)u.activo=!u.activo;saveCollection('usuarios',a);render('usuarios')}
function newSubject(){modal('Nueva materia',`<form><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>Grupo<input name="grupo" value="3°A" required></label><label class="wide">Docente<input name="docente"></label></div><div class="actions"><button class="btn primary">Guardar</button></div></form>`,f=>{const a=getCollection('materias');a.push({id:uid('m'),nombre:f.get('nombre'),grupo:f.get('grupo'),docente:f.get('docente')});saveCollection('materias',a);document.getElementById('modalRoot').innerHTML='';render('materias');showToast('Materia agregada')})}
function newNotice(){modal('Nuevo aviso',`<form><div class="form-grid"><label class="wide">Título<input name="titulo" required></label><label class="wide">Texto<textarea name="texto" required></textarea></label><label>Fecha<input name="fecha" type="date" required></label></div><div class="actions"><button class="btn primary">Publicar</button></div></form>`,f=>{const a=getCollection('avisos');a.push({id:uid('av'),titulo:f.get('titulo'),texto:f.get('texto'),fecha:f.get('fecha')});saveCollection('avisos',a);document.getElementById('modalRoot').innerHTML='';render('avisos');showToast('Aviso publicado')})}function renderMaint(s,c){const r=getCollection('reportes');if(s==='inicio'){setHeader('Inicio');c.innerHTML=statCards([['Pendientes',r.filter(x=>x.estado==='PENDIENTE').length],['En revisión',r.filter(x=>x.estado==='EN_REVISION').length],['En proceso',r.filter(x=>x.estado==='EN_PROCESO').length],['Resueltos',r.filter(x=>x.estado==='RESUELTO').length]])+`<div class="section-head"><h2>Reportes recientes</h2></div><div class="card">${r.slice().reverse().slice(0,5).map(maintRow).join('')}</div>`}else if(s==='reportes'){setHeader('Reportes');c.innerHTML=`<div class="section-head"><h2>Gestión de reportes</h2></div><div class="card">${r.map(maintRow).join('')}</div>`}}
function maintRow(r){return `<div class="report-row"><div><strong>#${escapeHTML(r.id)} · ${escapeHTML(r.ubicacion)}</strong><small class="muted">${escapeHTML(r.descripcion)} · ${r.fecha}</small></div><div><select onchange="changeReport('${r.id}',this.value)">${['PENDIENTE','EN_REVISION','EN_PROCESO','RESUELTO'].map(s=>`<option ${s===r.estado?'selected':''}>${s}</option>`).join('')}</select></div></div>`}
function changeReport(id,status){const a=getCollection('reportes'),r=a.find(x=>x.id===id);if(r){r.estado=status;r.comentarios=r.comentarios||[];r.comentarios.push('Estado actualizado a '+status+' por mantenimiento.')}saveCollection('reportes',a);render('reportes');showToast('Estado actualizado')}function renderParent(s,c){const kids=getCollection('alumnos').filter(a=>user.hijos?.includes(a.id));if(s==='inicio'){setHeader('Inicio');c.innerHTML=statCards([['Tutelados',kids.length],['Tareas pendientes',getCollection('tareas').filter(t=>kids.some(k=>k.id===t.alumnoId)&&!t.completada).length],['Materias',getCollection('materias').filter(m=>kids.some(k=>k.grupo===m.grupo)).length],['Avisos',getCollection('avisos').length]])+`<div class="section-head"><h2>Mis hijos / tutelados</h2></div><div class="grid">${kids.map(k=>`<div class="card subject"><strong>${escapeHTML(k.nombre)}</strong><small>Grupo ${escapeHTML(k.grupo)}</small></div>`).join('')}</div>`}else if(s==='tareas'){setHeader('Tareas');c.innerHTML=kids.map(k=>`<div class="section-head"><h2>${escapeHTML(k.nombre)}</h2></div><div class="card">${getCollection('tareas').filter(t=>t.alumnoId===k.id).map(taskRow).join('')||'<div class="empty">Sin tareas.</div>'}</div>`).join('')}else if(s==='calendario'){setHeader('Calendario');c.innerHTML=`<div class="card"><div class="calendar">${Array.from({length:30},(_,i)=>`<div class="day"><b>${i+1}</b><small>${getCollection('eventos').filter(e=>e.fecha==='2026-09-'+String(i+1).padStart(2,'0')).map(e=>escapeHTML(e.titulo)).join('<br>')}</small></div>`).join('')}</div></div>`}else if(s==='materias'){setHeader('Materias');c.innerHTML=`<div class="grid">${getCollection('materias').filter(m=>kids.some(k=>k.grupo===m.grupo)).map(m=>`<div class="card subject"><strong>${escapeHTML(m.nombre)}</strong><small>${escapeHTML(m.docente)}</small><small>${escapeHTML(m.grupo)}</small></div>`).join('')}</div>`}else if(s==='plataformas'){setHeader('Plataformas');c.innerHTML=platformHTML()}else if(s==='avisos'){setHeader('Avisos');c.innerHTML=`<div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}}const path=location.pathname.toLowerCase();const role=path.includes('admin')?'ADMIN':path.includes('alumno')?'ALUMNO':path.includes('padre')?'PADRE':'MANTENIMIENTO';const user=requireRole(role);if(user){setupShell(role);document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>render(b.dataset.section));render('inicio')}function setHeader(title){document.getElementById('pageTitle').textContent=title;document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===title.toLowerCase().replaceAll(' ','_')))}
function statCards(items){return `<div class="stats">${items.map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div>`}
function alumnoId(){return user.alumnoId||'a1'}
function studentTasks(){return getCollection('tareas').filter(t=>t.alumnoId===alumnoId())}
function platformHTML(){return `<div class="platform-grid">${getCollection('plataformas').map(p=>`<div class="card platform-card"><div><strong>${escapeHTML(p.nombre)}</strong><p class="muted">${escapeHTML(p.descripcion)}</p></div><a class="btn secondary" href="${escapeHTML(p.url)}" target="_blank" rel="noopener">Abrir ↗</a></div>`).join('')}</div>`}
function render(section){const c=document.getElementById('content');if(role==='ADMIN')return renderAdmin(section,c);if(role==='MANTENIMIENTO')return renderMaint(section,c);if(role==='PADRE')return renderParent(section,c);return renderStudent(section,c)}
function renderStudent(s,c){const tasks=studentTasks();if(s==='inicio'){setHeader('Inicio');c.innerHTML=statCards([['Tareas pendientes',tasks.filter(x=>!x.completada).length],['Próxima entrega',tasks.filter(x=>!x.completada).sort((a,b)=>a.fecha.localeCompare(b.fecha))[0]?.fecha||'—'],['Materias',getCollection('materias').filter(m=>m.grupo==='3°A').length],['Mis reportes',getCollection('reportes').filter(r=>r.usuarioId===user.id).length]])+`<div class="section-head"><h2>Próximas tareas</h2><button class="btn primary" onclick="render('tareas')">Ver tareas</button></div><div class="card">${tasks.filter(x=>!x.completada).slice(0,4).map(taskRow).join('')||'<div class="empty">No tienes tareas pendientes.</div>'}</div><div class="section-head"><h2>Avisos</h2></div><div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}else if(s==='tareas'){setHeader('Tareas');c.innerHTML=`<div class="section-head"><h2>Mis tareas</h2><button class="btn primary" onclick="newTask()">+ Nueva tarea</button></div><div class="card">${tasks.map(taskRow).join('')||'<div class="empty">No hay tareas.</div>'}</div>`}else if(s==='calendario'){setHeader('Calendario');c.innerHTML=`<div class="card"><div class="calendar">${Array.from({length:30},(_,i)=>{const d=i+1;const date='2026-09-'+String(d).padStart(2,'0');const ev=getCollection('eventos').filter(e=>e.fecha===date);return `<div class="day"><b>${d}</b><small>${ev.map(e=>escapeHTML(e.titulo)).join('<br>')}</small></div>`}).join('')}</div></div>`}else if(s==='materias'){setHeader('Materias');c.innerHTML=`<div class="grid">${getCollection('materias').filter(m=>m.grupo==='3°A').map(m=>`<div class="card subject"><strong>${escapeHTML(m.nombre)}</strong><small>${escapeHTML(m.docente)}</small><small>Grupo: ${escapeHTML(m.grupo)}</small></div>`).join('')}</div>`}else if(s==='plataformas'){setHeader('Plataformas');c.innerHTML=`<div class="section-head"><h2>Mis plataformas</h2><button class="btn primary" onclick="newPlatform()">+ Agregar</button></div>${platformHTML()}`}else if(s==='reportes'){setHeader('Reportes');renderReportsStudent(c)}else if(s==='avisos'){setHeader('Avisos');c.innerHTML=`<div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}}
function taskRow(t){return `<div class="task-row"><div class="row-main"><input class="check" type="checkbox" ${t.completada?'checked':''} onchange="toggleTask('${t.id}')"><div><strong>${escapeHTML(t.titulo)}</strong><small>${escapeHTML(t.materia)} · Entrega ${t.fecha}</small></div></div><span class="badge">${t.completada?'COMPLETADA':'PENDIENTE'}</span></div>`}
function toggleTask(id){const a=getCollection('tareas');const t=a.find(x=>x.id===id);if(t)t.completada=!t.completada;saveCollection('tareas',a);render('tareas');showToast('Tarea actualizada')}
function newTask(){modal('Nueva tarea',`<form><div class="form-grid"><label class="wide">Título<input name="titulo" required></label><label>Materia<input name="materia" required></label><label>Fecha<input name="fecha" type="date" required></label></div><div class="actions"><button class="btn secondary" type="button" onclick="document.getElementById('modalRoot').innerHTML=''">Cancelar</button><button class="btn primary">Guardar</button></div></form>`,f=>{const a=getCollection('tareas');a.push({id:uid('t'),alumnoId:alumnoId(),titulo:f.get('titulo'),materia:f.get('materia'),fecha:f.get('fecha'),completada:false});saveCollection('tareas',a);document.getElementById('modalRoot').innerHTML='';render('tareas');showToast('Tarea creada')})}
function newPlatform(){modal('Agregar plataforma',`<form><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>URL<input name="url" type="url" required placeholder="https://..."></label><label class="wide">Descripción<textarea name="descripcion"></textarea></label></div><div class="actions"><button class="btn secondary" type="button" onclick="document.getElementById('modalRoot').innerHTML=''">Cancelar</button><button class="btn primary">Guardar</button></div></form>`,f=>{const a=getCollection('plataformas');a.push({id:uid('p'),nombre:f.get('nombre'),url:f.get('url'),descripcion:f.get('descripcion')});saveCollection('plataformas',a);document.getElementById('modalRoot').innerHTML='';render('plataformas');showToast('Plataforma agregada')})}
function renderReportsStudent(c){const rs=getCollection('reportes').filter(r=>r.usuarioId===user.id);c.innerHTML=`<div class="section-head"><h2>Mis reportes</h2><button class="btn primary" onclick="newReport()">+ Nuevo reporte</button></div><div class="card">${rs.map(reportRow).join('')||'<div class="empty">No has creado reportes.</div>'}</div>`}
function reportRow(r){return `<div class="report-row"><div><strong>#${escapeHTML(r.id)}</strong> · ${escapeHTML(r.ubicacion)}<small class="muted">${escapeHTML(r.descripcion)} · ${r.fecha}</small></div><span class="badge status-${r.estado}">${r.estado.replaceAll('_',' ')}</span></div>`}
function newReport(){modal('Nuevo reporte',`<form><div class="form-grid"><label>Ubicación<input name="ubicacion" required></label><label>Fecha<input name="fecha" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="wide">Descripción<textarea name="descripcion" required></textarea></label></div><div class="actions"><button class="btn secondary" type="button" onclick="document.getElementById('modalRoot').innerHTML=''">Cancelar</button><button class="btn primary">Enviar reporte</button></div></form>`,f=>{const a=getCollection('reportes');a.push({id:String(a.length+1).padStart(3,'0'),ubicacion:f.get('ubicacion'),descripcion:f.get('descripcion'),usuarioId:user.id,fecha:f.get('fecha'),estado:'PENDIENTE',comentarios:[]});saveCollection('reportes',a);document.getElementById('modalRoot').innerHTML='';render('reportes');showToast('Reporte enviado')})}